func resolveRuntime(getenv func(string) string, lookPath func(string) (string, error)) runtimeInfo {
	var info runtimeInfo
	if p := strings.TrimSpace(getenv("BLENDER_BIN")); p != "" {
		info.BlenderPath = p
		info.Sources = append(info.Sources, "BLENDER_BIN")
	} else {
		for _, name := range []string{"blender", "blender.exe"} {
			if p, err := lookPath(name); err == nil && p != "" {
				info.BlenderPath = p
				info.Sources = append(info.Sources, "PATH:"+name)
				break
			}
		}
	}
	if info.BlenderPath == "" {
		for _, candidate := range defaultBlenderCandidates() {
			if fileExists(candidate) {
				info.BlenderPath = candidate
				info.Sources = append(info.Sources, "well-known-path")
				break
			}
		}
	}

	if p := strings.TrimSpace(getenv("BLENDER_MCP_BIN")); p != "" {
		info.BlenderMCPPath = p
		info.Sources = append(info.Sources, "BLENDER_MCP_BIN")
	} else if p, err := lookPath("blender-mcp"); err == nil && p != "" {
		info.BlenderMCPPath = p
		info.Sources = append(info.Sources, "PATH:blender-mcp")
	}

	switch {
	case info.BlenderPath != "" && info.BlenderMCPPath != "":
		info.Mode = "headless+tandem"
	case info.BlenderPath != "":
		info.Mode = "headless"
	case info.BlenderMCPPath != "":
		info.Mode = "tandem"
	default:
		info.Mode = "unresolved"
	}
	return info
}

