func importScript(assetPath, outputBlend, collection string) string {
	return fmt.Sprintf(`
import json, pathlib, bpy
asset = %q
out = %q
collection_name = %q
bpy.ops.object.select_all(action='SELECT')
bpy.ops.object.delete()
collection = bpy.data.collections.new(collection_name)
bpy.context.scene.collection.children.link(collection)
ext = pathlib.Path(asset).suffix.lower()
if ext in [".glb", ".gltf"]:
    bpy.ops.import_scene.gltf(filepath=asset)
elif ext == ".obj":
    bpy.ops.wm.obj_import(filepath=asset)
elif ext in [".fbx"]:
    bpy.ops.import_scene.fbx(filepath=asset)
elif ext in [".stl"]:
    bpy.ops.wm.stl_import(filepath=asset)
else:
    raise SystemExit("unsupported import extension: " + ext)
for obj in bpy.context.selected_objects:
    for col in list(obj.users_collection):
        col.objects.unlink(obj)
    collection.objects.link(obj)
bpy.ops.wm.save_as_mainfile(filepath=out)
print("BLENDER_PP_JSON_BEGIN")
print(json.dumps({"source_asset": asset, "output_blend": out, "objects": [o.name for o in collection.objects]}, indent=2))
print("BLENDER_PP_JSON_END")
`, assetPath, outputBlend, collection)
}

