func turntableScript(outputPath, engine string, frames int) string {
	return fmt.Sprintf(`
import json, math, bpy
bpy.context.scene.frame_start = 1
bpy.context.scene.frame_end = %d
bpy.context.scene.render.engine = %q
target = bpy.context.scene.objects[0] if bpy.context.scene.objects else None
if target:
    target.rotation_euler[2] = 0
    target.keyframe_insert(data_path="rotation_euler", frame=1)
    target.rotation_euler[2] = math.radians(360)
    target.keyframe_insert(data_path="rotation_euler", frame=%d)
bpy.context.scene.render.filepath = %q
bpy.ops.wm.save_as_mainfile(filepath=%q)
print("BLENDER_PP_JSON_BEGIN")
print(json.dumps({"output_blend": %q, "frames": %d, "engine": bpy.context.scene.render.engine}, indent=2))
print("BLENDER_PP_JSON_END")
`, frames, engine, frames, outputPath, outputPath, outputPath, frames)
}
